import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride,
                             int pad);
"""

conv_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled 2D convolution (dilation=1, groups=1).
// The convolution is evaluated as a tiled matmul-like reduction:
//   Y[co, p] = bias[co] + sum_k W[co, k] * Xpatch[p, k]
// where p = (n, oh, ow) enumerates all output spatial positions over the batch,
// and k = (c, kh, kw) enumerates the reduction dimension C_in*KH*KW.
// Each CTA computes a TILE_CO x TILE_P tile of the (C_out, P_total) "output matrix".
__global__ void conv2d_tiled_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int N, int C_in, int H, int W_in,
    int C_out, int KH, int KW,
    int stride, int pad,
    int Hout, int Wout, int P_total)
{
  constexpr int TILE_P  = 64;   // output positions per CTA
  constexpr int TILE_CO = 64;   // output channels per CTA
  constexpr int KC      = 32;   // reduction chunk
  constexpr int THREADS = 256;

  const int tid = threadIdx.x;
  const int bx  = blockIdx.x;   // tile along P
  const int by  = blockIdx.y;   // tile along CO

  const int K_total = C_in * KH * KW;

  // Shared memory staging (padded leading dims to avoid bank conflicts)
  __shared__ float smemW[TILE_CO * KC + KC];  // (CO, K) : stride (1, TILE_CO+1)
  __shared__ float smemX[TILE_P  * KC + KC];  // (P,  K) : stride (1, TILE_P +1)

  Tensor sW = make_tensor(make_smem_ptr(smemW),
                          make_layout(make_shape(Int<TILE_CO>{}, Int<KC>{}),
                                      make_stride(Int<1>{}, Int<TILE_CO + 1>{})));
  Tensor sX = make_tensor(make_smem_ptr(smemX),
                          make_layout(make_shape(Int<TILE_P>{}, Int<KC>{}),
                                      make_stride(Int<1>{}, Int<TILE_P + 1>{})));

  // Global output viewed as a (C_out, P_total) column-major matrix:
  // Y[n, co, oh, ow] contiguous => offset = co * P_total + p
  Tensor mC = make_tensor(make_gmem_ptr(Y),
                          make_shape(C_out, P_total),
                          make_stride((int64_t)P_total, Int<1>{}));
  Tensor gC = local_tile(mC,
                         make_shape(Int<TILE_CO>{}, Int<TILE_P>{}),
                         make_coord(by, bx));

  // Thread layout: 16x16 threads, each owns a 4x4 sub-tile
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  Tensor tCsW = local_partition(sW, tC, tid, Step<_1,  X>{});  // (4, KC)
  Tensor tCsX = local_partition(sX, tC, tid, Step< X, _1>{});  // (4, KC)
  Tensor tCgC = local_partition(gC, tC, tid);                  // (4, 4)

  Tensor tCrC = make_tensor_like(tCgC);  // register accumulator
  clear(tCrC);

  for (int k0 = 0; k0 < K_total; k0 += KC) {
    // Stage weights tile: sW(co_l, k_l) = W[(by*TILE_CO+co_l)*K_total + k0+k_l]
    #pragma unroll
    for (int i = 0; i < (TILE_CO * KC) / THREADS; ++i) {
      int e    = tid + i * THREADS;
      int co_l = e / KC;
      int k_l  = e - co_l * KC;
      int co_g = by * TILE_CO + co_l;
      int k_g  = k0 + k_l;
      float v  = 0.0f;
      if (co_g < C_out && k_g < K_total) {
        v = W[(int64_t)co_g * K_total + k_g];
      }
      sW(co_l, k_l) = v;
    }

    // Stage im2col input tile: sX(p_l, k_l) = X[n, c, oh*stride-pad+kh, ow*stride-pad+kw]
    #pragma unroll
    for (int i = 0; i < (TILE_P * KC) / THREADS; ++i) {
      int e   = tid + i * THREADS;
      int p_l = e / KC;              // threads iterate k fastest -> coalesced gmem reads
      int k_l = e - p_l * KC;
      int p_g = bx * TILE_P + p_l;
      int k_g = k0 + k_l;
      float v = 0.0f;
      if (p_g < P_total && k_g < K_total) {
        int kw = k_g % KW;
        int t  = k_g / KW;
        int kh = t % KH;
        int c  = t / KH;

        int HW = Hout * Wout;
        int n  = p_g / HW;
        int r  = p_g - n * HW;
        int oh = r / Wout;
        int ow = r - oh * Wout;

        int ih = oh * stride - pad + kh;
        int iw = ow * stride - pad + kw;
        if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)W_in) {
          v = X[(((int64_t)n * C_in + c) * H + ih) * W_in + iw];
        }
      }
      sX(p_l, k_l) = v;
    }

    __syncthreads();

    // C(4,4) += A(4,KC) * B(4,KC)^T on register fragments
    gemm(tCsW, tCsX, tCrC);

    __syncthreads();
  }

  // Epilogue: add bias and store with bounds checks
  Tensor cC   = make_identity_tensor(make_shape(Int<TILE_CO>{}, Int<TILE_P>{}));
  Tensor tCcC = local_partition(cC, tC, tid);

  #pragma unroll
  for (int i = 0; i < size(tCrC); ++i) {
    auto coord = tCcC(i);
    int co_g = by * TILE_CO + get<0>(coord);
    int p_g  = bx * TILE_P  + get<1>(coord);
    if (co_g < C_out && p_g < P_total) {
      float bias_v = (B != nullptr) ? B[co_g] : 0.0f;
      tCgC(i) = tCrC(i) + bias_v;
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride,
                             int pad) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C_in, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C_out, C_in, KH, KW]");
  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(pad >= 0, "pad must be >= 0");

  int64_t N     = x.size(0);
  int64_t C_in  = x.size(1);
  int64_t H     = x.size(2);
  int64_t W_in  = x.size(3);
  int64_t C_out = w.size(0);
  int64_t KH    = w.size(2);
  int64_t KW    = w.size(3);
  TORCH_CHECK(w.size(1) == C_in, "w.size(1) must equal C_in");

  int64_t Hout = (H + 2 * pad - KH) / stride + 1;
  int64_t Wout = (W_in + 2 * pad - KW) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const float* b_ptr = nullptr;
  torch::Tensor b_c;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat, "bias must be CUDA float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C_out, "bias must be [C_out]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, C_out, Hout, Wout}, x.options());

  int64_t P_total = N * Hout * Wout;

  constexpr int TILE_P  = 64;
  constexpr int TILE_CO = 64;

  dim3 block(256);
  dim3 grid((unsigned)((P_total + TILE_P - 1) / TILE_P),
            (unsigned)((C_out  + TILE_CO - 1) / TILE_CO));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_tiled_kernel<<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C_in, (int)H, (int)W_in,
      (int)C_out, (int)KH, (int)KW,
      stride, pad,
      (int)Hout, (int)Wout, (int)P_total);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_tiled_ext",
    cpp_sources=conv_cpp_decl,
    cuda_sources=conv_cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        # Same parameter layout/names as the reference model so weights can be
        # transferred directly.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11,
                               stride=4, padding=2)
        self._ext = conv2d_ext

    def forward(self, x):
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.conv1.weight.contiguous(),
            self.conv1.bias,
            4,   # stride
            2,   # pad
        )

